79	func TestFroms(t *testing.T) {
80		p := make([]byte, 1<<20)
81		_, err := rand.Read(p)
82		if err != nil {
83			t.Fatal(err)
84		}
85	
86		for alg := range algorithms {
87			t.Run(string(alg), func(t *testing.T) {
88				h := alg.Hash()
89				h.Write(p)
90				expected := Digest(fmt.Sprintf("%s:%x", alg, h.Sum(nil)))
91	
92				var readerDgst Digest
93				readerDgst, err = alg.FromReader(bytes.NewReader(p))
94				if err != nil {
95					t.Fatalf("error calculating hash from reader: %v", err)
96				}
97	
98				dgsts := []Digest{
99					alg.FromBytes(p),
100					alg.FromString(string(p)),
101					readerDgst,
102				}
103	
104				if alg == Canonical {
105					readerDgst, err = FromReader(bytes.NewReader(p))
106					if err != nil {
107						t.Fatalf("error calculating hash from reader: %v", err)
108					}
109	
110					dgsts = append(dgsts,
111						FromBytes(p),
112						FromString(string(p)),
113						readerDgst)
114				}
115				for _, dgst := range dgsts {
116					if dgst != expected {
117						t.Errorf("unexpected digest %v != %v", dgst, expected)
118					}
119				}
120			})
121		}
122	}
