143	func TestGoodAlgorithmNameRegistration(t *testing.T) {
144		expectNoPanic := func(algorithm string) {
145			defer func() {
146				r := recover()
147				if r != nil {
148					t.Fatalf("Expected panic and found one: %v", r)
149				}
150			}()
151	
152			// We just use SHA256 here as a test / stand-in
153			RegisterAlgorithm(Algorithm(algorithm), crypto.SHA256)
154		}
155	
156		expectNoPanic("sha256-test")
157		expectNoPanic("sha256_384")
158	}
