10	// stringWriter is a wrapper around a pair of (strings.Builder, *string)
11	// which can conditionally discard writes.
12	type stringWriter struct {
13		// builder is meant to be used for handling escapes, in which
14		// case we cannot get away with slicing the original string,
15		// and we need to allocate a new string.
16		builder strings.Builder
17		// finalCopySlot represents the final destination for the write.
18		// If nil, no writes are performed.
19		finalCopySlot *string
20	}
21	
22	// append appends the given string to the accumulated string.
23	func (w *stringWriter) append(s string) {
24		if w.finalCopySlot == nil {
25			return
26		}
27		w.builder.WriteString(s)
28	}
29	
30	// finish copies the accumulated string to the final destination,
31	// if present.
32	func (w *stringWriter) finish() {
33		if w.finalCopySlot == nil {
34			return
35		}
36		*w.finalCopySlot = w.builder.String()
37	}
38	
39	// writeFullAndFinish ignores any previous writes via append calls
40	// and writes the given string.
41	func (w *stringWriter) writeFullAndFinish(s string) {
42		if w.finalCopySlot == nil {
43			return
44		}
45		*w.finalCopySlot = s
46	}
