48	// normalize overwrites the string in the slot if it matches 'from'.
49	func (w *stringWriter) normalize(from string, to string) {
50		if w.finalCopySlot == nil || (*w.finalCopySlot != from) {
51			return
52		}
53		*w.finalCopySlot = to
54	}
