61	// parseSymbolV2 parses an SCIP string into the Symbol message
62	// with the option to exclude the `.Descriptor` field.
63	//
64	// Pre-condition: symbolUTF8 is non-empty.
65	func parseSymbolV2(symbolUTF8 beaut.UTF8String, includeDescriptors bool, out *Symbol) error {
66		symbol := symbolUTF8.RawValue()
67		isLocal, err := tryParseLocalSymbolV2(symbol, out)
68		if isLocal || err != nil {
69			return err
70		}
71		z := newSymbolParserV2(symbol)
72		var sw stringWriter
73		if out != nil {
74			sw.reset(&out.Scheme)
75		}
76		if err = z.acceptSpaceEscapedIdentifier(parseCtxScheme, &sw); err != nil {
77			return err
78		}
79		if out != nil {
80			if out.Package == nil {
81				out.Package = &Package{}
82			}
83			sw.reset(&out.Package.Manager)
84		}
85		if err := z.acceptSpaceEscapedIdentifier(parseCtxPackageManager, &sw); err != nil {
86			return err
87		}
88		sw.normalize(".", "")
89		if out != nil {
90			sw.reset(&out.Package.Name)
91		}
92		if err := z.acceptSpaceEscapedIdentifier(parseCtxPackageName, &sw); err != nil {
93			return err
94		}
95		sw.normalize(".", "")
96		if out != nil {
97			sw.reset(&out.Package.Version)
98		}
99		if err := z.acceptSpaceEscapedIdentifier(parseCtxPackageVersion, &sw); err != nil {
100			return err
101		}
102		sw.normalize(".", "")
103	
104		if includeDescriptors {
105			var dw descriptorsWriter
106			if out != nil {
107				dw.shouldWrite = true
108				dw.descriptors = out.Descriptors
109			}
110			if err := z.parseDescriptors(&dw); err != nil {
111				return err
112			}
113			if out != nil {
114				out.Descriptors = dw.validDescriptors()
115			}
116		}
117		return nil
118	}
