120	func tryParseLocalSymbolV2(s string, out *Symbol) (bool, error) {
121		suffix := strings.TrimPrefix(s, "local ")
122		if len(suffix) == len(s) {
123			return false, nil
124		}
125		if len(suffix) == 0 || !isSimpleIdentifier(suffix) {
126			return false, expectedSimpleIdentifierError{""}
127		}
128		if out != nil {
129			out.Scheme = "local"
130			// This is a bit unfortunate; we cannot avoid allocating another Package value
131			// in the next parsing call if the next Symbol received is not a local variable.
132			out.Package = nil
133			if len(out.Descriptors) == 0 {
134				out.Descriptors = []*Descriptor{{Name: suffix, Suffix: Descriptor_Local}}
135			} else {
136				d := out.Descriptors[0]
137				d.Name = suffix
138				d.Disambiguator = ""
139				d.Suffix = Descriptor_Local
140				out.Descriptors = out.Descriptors[:1]
141			}
142		}
143		return true, nil
144	}
