154	// descriptorsWriter encapsulates the logic for writing descriptors
155	// while handling the zero-write/validation-only case.
156	type descriptorsWriter struct {
157		// descriptors represents the Descriptor values that should be written
158		// to. Only count elements of this slice should be interpreted.
159		descriptors []*Descriptor
160		// tmpStringWriter will discard writes if shouldWrite is false.
161		// Otherwise, it may be a name writer or a disambiguator writer.
162		tmpStringWriter stringWriter
163		// throwawaySuffix is for the !shouldWrite case, where we still
164		// want to provide a uniform type for the caller to "write" the
165		// suffix to (i.e. a pointer). If shouldWrite is true,
166		// then suffixes will be written to descriptors directly.
167		throwawaySuffix Descriptor_Suffix
168		count           int32
169		// shouldWrite controls if writes should be performed or discarded.
170		shouldWrite bool
171	}
172	
173	// prepareName appends a descriptor with the given suffix and an empty
174	// name and disambiguator, and returns a writer for the name.
175	//
176	// For writing the disambiguator, use getDisambiguatorForLast after
177	// calling prepare or prepareName.
178	//
179	// Pre-condition: Writes to a previously written writer from {prepare,
180	// prepareName, getDisambiguatorForLast} must be finished before calling
181	// any of these methods again.
182	func (dw *descriptorsWriter) prepareName(suffix Descriptor_Suffix) *stringWriter {
183		if dw.shouldWrite {
184			dw.tmpStringWriter.builder.Reset()
185			dw.tmpStringWriter.finalCopySlot, _ = dw.internalPrepareSlot(suffix)
186		}
187		return &dw.tmpStringWriter
188	}
189	
190	// prepare is similar to prepareName, but allows delaying writing the suffix.
191	//
192	// Pre-condition: Writes to a previously written writer from {prepare,
193	// prepareName, getDisambiguatorForLast} must be finished before calling
194	// any of these methods again.
195	func (dw *descriptorsWriter) prepare() (*stringWriter, *Descriptor_Suffix) {
196		suffixPtr := &dw.throwawaySuffix
197		if dw.shouldWrite {
198			dw.tmpStringWriter.builder.Reset()
199			dw.tmpStringWriter.finalCopySlot, suffixPtr = dw.internalPrepareSlot(Descriptor_UnspecifiedSuffix)
200		}
201		return &dw.tmpStringWriter, suffixPtr
202	}
203	
204	// getDisambiguatorForLast returns a writer for the disambiguator for the last
205	// descriptor that was inserted.
206	//
207	// Pre-condition: prepare or prepareName must have been called before this.
208	//
209	// Pre-condition: Writes to a previously written writer from {prepare,
210	// prepareName, getDisambiguatorForLast} must be finished before calling
211	// any of these methods again.
212	func (dw *descriptorsWriter) getDisambiguatorForLast() *stringWriter {
213		if dw.shouldWrite {
214			dw.tmpStringWriter.builder.Reset()
215			dw.tmpStringWriter.finalCopySlot = &dw.descriptors[dw.count-1].Disambiguator
216			return &dw.tmpStringWriter
217		}
218		return &dw.tmpStringWriter
219	}
