221	// internalPrepareSlot optionally grows the slice of descriptors, assigns the provided
222	// suffix to the last descriptor, and returns pointers to the 'Name' and
223	// 'Suffix' fields for overwriting.
224	//
225	// Generally, higher-level code should only call prepare or prepareName.
226	//
227	// Pre-condition: This should only be called in the shouldWrite case.
228	func (dw *descriptorsWriter) internalPrepareSlot(suffix Descriptor_Suffix) (*string, *Descriptor_Suffix) {
229		assert(dw.shouldWrite, "should only call internalPrepareSlot in the shouldWrite case")
230		zeroLastSlot := func() {
231			lastPtr := &dw.descriptors[dw.count]
232			if last := *lastPtr; last == nil {
233				*lastPtr = &Descriptor{Suffix: suffix}
234			} else {
235				last.Name = ""
236				last.Suffix = suffix
237				last.Disambiguator = ""
238			}
239		}
240		if len(dw.descriptors) == int(dw.count) {
241			dw.descriptors = append(dw.descriptors, &Descriptor{Suffix: suffix})
242		} else {
243			zeroLastSlot()
244		}
245		elt := dw.descriptors[dw.count]
246		dw.count++
247		nameSlot := &elt.Name
248		suffixSlot := &elt.Suffix
249		return nameSlot, suffixSlot
250	}
