256	// symbolParserV2 parses symbols while minimizing heap allocations.
257	type symbolParserV2 struct {
258		SymbolString string
259		// byteIndex is the index in SymbolString for the first byte of currentRune.
260		// However, at the end of parsing, this can be equal to len(SymbolString);
261		// see advanceOneByte.
262		byteIndex       int
263		currentRune     rune
264		bytesToNextRune int32
