267	// findRuneAtIndex returns the rune at the given index.
268	//
269	// Pre-condition: string is well-formed UTF-8
270	// Pre-condition: byteIndex is in bounds
271	//
272	// NOTE: We could technically use utf8.DecodeRuneInString here, but that
273	// has a more complex implementation which tries to handle invalid UTF-8.
274	// Looking at the code itself, it seems like it would be slower given that
275	// it is doing more operations.
276	//
277	// https://sourcegraph.com/github.com/golang/go/-/blob/src/unicode/utf8/utf8.go?L205-243
278	//
279	// It might be worth benchmarking to see if that's faster/doesn't make
280	// a difference.
281	func findRuneAtIndex(s string, byteIndex int) (r rune, bytesRead int32) {
282		b1 := s[byteIndex]
283		if b1 < 0x80 {
284			return rune(b1), 1
285		}
286		b2 := s[byteIndex+1]
287		if b1&0b11100000 == 0b11000000 {
288			return (int32(b1&0b00011111) << 6) | int32(b2&0b00111111), 2
289		}
290		b3 := s[byteIndex+2]
291		if b1&0b11110000 == 0b11100000 {
292			return (int32(b1&0b00001111) << 12) | (int32(b2&0b00111111) << 6) | int32(b3&0b00111111), 3
293		}
294		b4 := s[byteIndex+3]
295		return (int32(b1&0b00000111) << 18) | (int32(b2&0b00111111) << 12) | (int32(b3&0b00111111) << 6) | int32(b4&0b00111111), 4
296	}
