298	// Pre-condition: string is well-formed UTF-8
299	// Pre-condition: len(symbol) > 0
300	func newSymbolParserV2(symbol string) symbolParserV2 {
301		r, bytesRead := findRuneAtIndex(symbol, 0)
302		return symbolParserV2{
303			SymbolString:    symbol,
304			byteIndex:       0,
305			currentRune:     r,
306			bytesToNextRune: bytesRead,
307		}
308	}
