363	func (z *symbolParserV2) error(e errorCase, expectedByte byte, what parseCtx) error {
364		switch e {
365		case errorCaseEmptyIdent:
366			return fmt.Errorf("failed to parse: %q (context: %v)", z.SymbolString, what)
367		case errorCaseByteNotFound:
368			return fmt.Errorf("failed to parse: %q (expected byte: %c, context: %v)", z.SymbolString, rune(expectedByte), what)
