374	func (z *symbolParserV2) peekNext() (rune, int32) {
375		if z.byteIndex+1 < len(z.SymbolString) {
376			return findRuneAtIndex(z.SymbolString, z.byteIndex+int(z.bytesToNextRune))
377		}
378		return 0, 0
379	}
