381	func (z *symbolParserV2) parseDescriptors(out *descriptorsWriter) error {
382		for z.byteIndex < len(z.SymbolString) {
383			if err := z.parseDescriptor(out); err != nil {
384				return err
385			}
386		}
387		return nil
