390	func (z *symbolParserV2) advance(nextRune rune, nextRuneByteLength int32) {
391		z.byteIndex += int(z.bytesToNextRune)
392		z.currentRune = nextRune
393		z.bytesToNextRune = nextRuneByteLength
394	}
