396	func (z *symbolParserV2) parseDescriptor(out *descriptorsWriter) error {
397		start := z.byteIndex
398		switch z.currentRune {
399		case '(':
400			z.advanceOneByte('(')
401			nameWriter := out.prepareName(Descriptor_Parameter)
402			if err := z.acceptIdentifier(parseCtxParameterName, nameWriter); err != nil {
403				return err
404			}
405			return z.acceptOneByte(')', parseCtxClosingParameterName)
406		case '[':
407			z.advanceOneByte('[')
408			nameWriter := out.prepareName(Descriptor_TypeParameter)
409			if err := z.acceptIdentifier(parseCtxTypeParameterName, nameWriter); err != nil {
410				return err
411			}
412			return z.acceptOneByte(']', parseCtxClosingTypeParameterName)
413		default:
414			nameWriter, descriptorPtr := out.prepare()
415			if err := z.acceptIdentifier(parseCtxDescriptorName, nameWriter); err != nil {
416				return err
417			}
418			suffixRune := z.currentRune
419			z.advanceRune()
420			switch suffixRune {
421			case '(':
422				*descriptorPtr = Descriptor_Method
423				if z.currentRune != ')' {
424					disambWriter := out.getDisambiguatorForLast()
425					if err := z.acceptIdentifier(parseCtxMethodDisambiguator, disambWriter); err != nil {
426						return err
427					}
428				}
429				if err := z.acceptOneByte(')', parseCtxClosingMethod); err != nil {
430					return err
431				}
432				return z.acceptOneByte('.', parseCtxClosingMethod)
433			case '/':
434				*descriptorPtr = Descriptor_Namespace
435				return nil
436			case '.':
437				*descriptorPtr = Descriptor_Term
438				return nil
439			case '#':
440				*descriptorPtr = Descriptor_Type
441				return nil
442			case ':':
443				*descriptorPtr = Descriptor_Meta
444				return nil
445			case '!':
446				*descriptorPtr = Descriptor_Macro
447				return nil
448			default:
449			}
450		}
451	
452		end := z.byteIndex
453		if z.byteIndex > len(z.SymbolString) {
454			end = len(z.SymbolString)
455		}
456		return unrecognizedDescriptorError{z.SymbolString[start:end]}
457	}
458	
459	type unrecognizedDescriptorError struct {
460		value string
461	}
462	
463	var _ error = unrecognizedDescriptorError{}
464	
465	func (e unrecognizedDescriptorError) Error() string {
466		return fmt.Sprintf("unrecognized descriptor %q", e.value)
467	}
