469	func (z *symbolParserV2) advanceOneByte(b byte) {
470		assert(z.currentRune == rune(b), "passed in byte does not match current rune")
471		nextRune, nextRuneByteLength := z.peekNext()
472		// CAUTION: z.byteIndex can become equal to len(z.SymbolString) here
473		z.byteIndex += 1
474		z.currentRune = nextRune
475		z.bytesToNextRune = nextRuneByteLength
476	}
477	
478	func (z *symbolParserV2) advanceRune() {
479		nextRune, nextRuneByteLength := z.peekNext()
480		z.advance(nextRune, nextRuneByteLength)
481	}
482	
483	func (z *symbolParserV2) acceptOneByte(b byte, what parseCtx) error {
484		if z.currentRune == rune(b) {
485			z.advanceOneByte(b)
486			return nil
487		}
488		return z.error(errorCaseByteNotFound, b, what)
489	}
490	
491	func (z *symbolParserV2) acceptIdentifier(what parseCtx, sw *stringWriter) error {
492		if z.currentRune == '`' {
493			z.advanceOneByte('`')
494			return z.acceptBacktickEscapedIdentifier(what, sw)
495		}
496		start := z.byteIndex
497		slen := len(z.SymbolString)
498		for z.byteIndex < slen {
499			if !isSimpleIdentifierCharacter(z.currentRune) {
500				break
501			}
502			z.advanceRune()
503		}
504		if start == z.byteIndex {
505			return z.error(errorCaseEmptyIdent, 0, what)
506		}
507		sw.writeFullAndFinish(z.SymbolString[start:z.byteIndex])
508		return nil
509	}
510	
511	func (z *symbolParserV2) acceptBacktickEscapedIdentifier(what parseCtx, sw *stringWriter) error {
512		return z.acceptTerminatedIdentifier(what, sw, '`')
513	}
514	
515	func (z *symbolParserV2) acceptSpaceEscapedIdentifier(what parseCtx, sw *stringWriter) error {
516		return z.acceptTerminatedIdentifier(what, sw, ' ')
517	}
518	
519	// acceptTerminatedIdentifier accepts an identifier that is terminated by 'terminator'.
520	//
521	// Consecutive occurrences of terminator are interpreted as a single literal character.
522	func (z *symbolParserV2) acceptTerminatedIdentifier(what parseCtx, sw *stringWriter, terminator byte) error {
523		slen := len(z.SymbolString)
524		terminatorRune := rune(terminator)
525		anchor := z.byteIndex
526		hasEscapedTerminator := false
527		for z.byteIndex < slen {
528			if z.currentRune != terminatorRune {
529				z.advanceRune()
530				continue
531			}
532			z.advanceOneByte(terminator)
533			if z.byteIndex == slen {
534				break
535			}
536			if z.currentRune == terminatorRune {
537				hasEscapedTerminator = true
538				// will include 1 copy of the terminator
539				sw.append(z.SymbolString[anchor:z.byteIndex])
540				z.advanceOneByte(terminator)
541				anchor = z.byteIndex
542				continue
543			}
544			if hasEscapedTerminator {
545				// Append the rest to the builder and return
546				sw.append(z.SymbolString[anchor : z.byteIndex-1])
547				sw.finish()
548				return nil
549			}
550			// In the non-escaped case, z.byteIndex is already 1 past the
551			// terminator, so do an extra -1
552			sw.writeFullAndFinish(z.SymbolString[anchor : z.byteIndex-1])
553			return nil
554		}
555		return endOfSymbolError{what, terminatorRune}
556	}
557	
558	type endOfSymbolError struct {
559		what     parseCtx
560		expected rune
561	}
562	
563	var _ error = endOfSymbolError{}
564	
565	func (e endOfSymbolError) Error() string {
566		return fmt.Sprintf("reached end of symbol while parsing <%s>, expected a '%v' character", e.what, e.expected)
567	}
568	
569	func (x *Package) ID() string {
570		return fmt.Sprintf("%s %s %s", x.Manager, x.Name, x.Version)
571	}
