36	pub fn try_parse_local_symbol(sym: &str) -> Result<Option<&str>, SymbolError> {
37	    if !sym.starts_with("local ") {
38	        return Ok(None);
39	    }
40	    let suffix = &sym[6..];
41	    if !suffix.is_empty() && is_simple_identifier(suffix) {
42	        return Ok(Some(suffix));
43	    }
44	    Err(SymbolError::InvalidLocalSymbol(sym.to_string()))
45	}
46	
47	pub struct SymbolFormatOptions {
48	    pub include_scheme: bool,
49	    pub include_package_manager: bool,
50	    pub include_package_name: bool,
51	    pub include_package_version: bool,
52	    pub include_descriptor: bool,
53	}
54	
55	impl SymbolFormatOptions {
56	    fn default() -> SymbolFormatOptions {
57	        SymbolFormatOptions {
58	            include_scheme: true,
59	            include_package_manager: true,
60	            include_package_name: true,
61	            include_package_version: true,
62	            include_descriptor: true,
63	        }
64	    }
65	}
66	
67	pub fn format_symbol_with(symbol: Symbol, options: SymbolFormatOptions) -> String {
68	    let mut parts = vec![];
69	    let Symbol {
70	        scheme,
71	        package: MessageField(package),
72	        descriptors,
73	        ..
74	    } = symbol;
75	
76	    // Handle local symbols first, to enforce simple formatting
77	    if scheme == "local" {
78	        if let Some(symbol) = descriptors
79	            .iter()
80	            .find_map(|desc| match desc.suffix.enum_value() {
81	                Ok(descriptor::Suffix::Local) => Some(format!("local {}", desc.name)),
82	                _ => None,
83	            })
84	        {
85	            return symbol;
86	        }
87	    }
88	
89	    if options.include_scheme {
90	        parts.push(scheme);
91	    }
92	
93	    if options.include_package_manager {
94	        match &package {
95	            Some(package) if !package.manager.is_empty() => parts.push(package.manager.clone()),
96	            _ => parts.push(".".to_string()),
97	        }
98	    }
99	
100	    if options.include_package_name {
101	        match &package {
102	            Some(package) if !package.name.is_empty() => parts.push(package.name.clone()),
103	            _ => parts.push(".".to_string()),
104	        }
105	    }
106	
107	    if options.include_package_version {
108	        match &package {
109	            Some(package) if !package.version.is_empty() => parts.push(package.version.clone()),
110	            _ => parts.push(".".to_string()),
111	        }
112	    }
113	
114	    if options.include_descriptor && !descriptors.is_empty() {
115	        parts.push(
116	            descriptors
117	                .iter()
118	                .filter_map(|desc| {
119	                    Some(match desc.suffix.enum_value() {
120	                        Ok(val) => {
121	                            let name = escape_name(&desc.name);
122	                            match val {
123	                                descriptor::Suffix::Package | descriptor::Suffix::Namespace => {
124	                                    format!("{}/", name)
125	                                }
126	                                descriptor::Suffix::Type => format!("{}#", name),
127	                                descriptor::Suffix::Term => format!("{}.", name),
128	                                descriptor::Suffix::Method => {
129	                                    format!("{}({}).", name, desc.disambiguator)
130	                                }
131	                                descriptor::Suffix::TypeParameter => format!("[{}]", name),
132	                                descriptor::Suffix::Parameter => format!("({})", name),
133	                                descriptor::Suffix::Macro => format!("{}!", name),
134	                                descriptor::Suffix::Meta => format!("{}:", name),
135	                                descriptor::Suffix::Local => format!("{}", name),
136	                                descriptor::Suffix::UnspecifiedSuffix => return None,
137	                            }
138	                        }
139	                        Err(_) => return None,
140	                    })
141	                })
142	                .collect::<Vec<String>>()
143	                .concat(),
144	        );
145	    }
146	
147	    parts.join(" ")
148	}
149	
150	fn escape_name(name: &str) -> String {
151	    if name
152	        .chars()
153	        .all(|ch| ch == '_' || ch == '+' || ch == '-' || ch == '$' || ch.is_ascii_alphanumeric())
154	    {
155	        name.to_string()
156	    } else {
157	        format!("`{}`", name.replace('`', "``"))
158	    }
159	}
160	
161	pub fn format_symbol(symbol: Symbol) -> String {
162	    format_symbol_with(symbol, SymbolFormatOptions::default())
163	}
