171	pub fn parse_symbol(symbol: &str) -> Result<Symbol, SymbolError> {
172	    fn dot(s: String) -> String {
173	        if s.as_str() == "." {
174	            "".to_string()
175	        } else {
176	            s
177	        }
178	    }
179	
180	    match try_parse_local_symbol(symbol) {
181	        Ok(Some(s)) => return Ok(internal_local_symbol(s)),
182	        Err(err) => return Err(err),
183	        Ok(None) => {},
184	    }
185	
186	    let mut parser = SymbolParser::new(symbol);
187	
188	    let scheme = parser.accept_space_escaped_identifier("scheme")?;
189	
190	    let package = crate::types::Package {
191	        manager: dot(parser.accept_space_escaped_identifier("package.manager")?),
192	        name: dot(parser.accept_space_escaped_identifier("package.name")?),
193	        version: dot(parser.accept_space_escaped_identifier("package.version")?),
194	        special_fields: SpecialFields::default(),
195	    };
196	
197	    // If all the package fields are empty, we can just say that package is None
198	    let package = match (
199	        package.manager.as_str(),
200	        package.name.as_str(),
201	        package.version.as_str(),
202	    ) {
203	        ("", "", "") => protobuf::MessageField::none(),
204	        _ => protobuf::MessageField::some(package),
205	    };
206	
207	    Ok(Symbol {
208	        scheme,
209	        package,
210	        descriptors: parser.accept_descriptors()?,
211	        special_fields: SpecialFields::default(),
212	    })
213	}
