237	#[derive(Debug)]
238	struct SymbolParser {
239	    sym: Vec<char>,
240	    index: usize,
241	}
242	
243	impl SymbolParser {
244	    fn new(sym: &str) -> Self {
245	        Self {
246	            sym: sym.chars().collect(),
247	            index: 0,
248	        }
249	    }
250	
251	    fn current(&self) -> Result<char, SymbolError> {
252	        self.sym
253	            .get(self.index)
254	            .cloned()
255	            .ok_or(SymbolError::InvalidIndex)
256	    }
257	
258	    fn peek_next(&self) -> Option<char> {
259	        self.sym.get(self.index + 1).cloned()
260	    }
261	
262	    fn accept_space_escaped_identifier(&mut self, what: &str) -> Result<String, SymbolError> {
263	        self.accept_escaped_identifier(what, ' ')
264	    }
265	
266	    fn accept_backtick_escpaed_identifier(&mut self, what: &str) -> Result<String, SymbolError> {
267	        self.accept_escaped_identifier(what, '`')
268	    }
269	
270	    fn accept_escaped_identifier(
271	        &mut self,
272	        what: &str,
273	        escape_char: char,
274	    ) -> Result<String, SymbolError> {
275	        let mut chars = vec![];
276	        let len = self.sym.len();
277	        while self.index < len {
278	            let ch = self.current()?;
279	            if ch == escape_char {
280	                self.index += 1;
281	                if self.current()? == escape_char {
282	                    chars.push(ch)
283	                } else {
284	                    return Ok(chars.into_iter().collect());
285	                }
286	            } else {
287	                chars.push(ch)
288	            }
289	
290	            self.index += 1;
291	        }
292	
293	        Err(SymbolError::EndOfSymbol(format!("Parsing {}", what)))
294	    }
295	
296	    fn accept_identifier(&mut self, what: &str) -> Result<String, SymbolError> {
297	        match self.current()? {
298	            '`' => {
299	                self.index += 1;
300	                Ok(self.accept_escaped_identifier(what, '`')?)
301	            }
302	            _ => {
303	                let start = self.index;
304	                while let Ok(c) = self.current() {
305	                    if !(c.is_alphabetic()
306	                        || c.is_digit(10)
307	                        || c == '-'
308	                        || c == '+'
309	                        || c == '$'
310	                        || c == '_')
311	                    {
312	                        break;
313	                    }
314	                    self.index += 1;
315	                }
316	
317	                if start == self.index {
318	                    Err(SymbolError::InvalidIdentifier(what.to_string()))
319	                } else {
320	                    Ok(self.sym[start..self.index].iter().collect())
321	                }
322	            }
323	        }
324	    }
325	
326	    fn accept_character(&mut self, c: char, what: &str) -> Result<char, SymbolError> {
327	        // if self.peek_next().ok_or(SymbolError::InvalidIndex)? == c {
328	        if self.current()? == c {
329	            self.index += 1;
330	            Ok(c)
331	        } else {
332	            Err(SymbolError::MissingCharacter(format!(
333	                "{}:: Expected: {}, Got: {}",
334	                what.to_string(),
335	                c,
336	                self.current()?
337	            )))
338	        }
339	    }
340	
341	    fn accept_descriptors(&mut self) -> Result<Vec<Descriptor>, SymbolError> {
342	        let mut v = Vec::new();
343	        let len = self.sym.len();
344	        while self.index < len {
345	            v.push(self.accept_one_descriptor()?)
346	        }
347	
348	        Ok(v)
349	    }
350	
351	    fn accept_one_descriptor(&mut self) -> Result<Descriptor, SymbolError> {
352	        match self.current()? {
353	            '(' => {
354	                self.accept_character('(', "Opening Parameter")?;
355	                let descriptor = new_descriptor(
356	                    self.accept_identifier("parameter name")?,
357	                    descriptor::Suffix::Parameter,
358	                );
359	                self.accept_character(')', "Closing Parameter")?;
360	                Ok(descriptor)
361	            }
362	            '[' => {
363	                self.accept_character('[', "Opening Type Parameter")?;
364	                let descriptor = new_descriptor(
365	                    self.accept_identifier("type parameter name")?,
366	                    descriptor::Suffix::TypeParameter,
367	                );
368	                self.accept_character(']', "Closing Type Parameter")?;
369	                Ok(descriptor)
370	            }
371	            _ => {
372	                let name = self.accept_identifier(
373	                    format!("descriptor name: {:?} / {}", self, self.sym.len()).as_str(),
374	                )?;
375	
376	                let suffix = self.current()?;
377	                self.index += 1;
378	                match suffix {
379	                    '(' => {
380	                        // We are not peeking here because we already advanced
381	                        // past suffix.
382	                        let disambiguator = match self.current()? {
383	                            ')' => "".to_string(),
384	                            _ => self.accept_identifier("method disambiguator")?,
385	                        };
386	
387	                        self.accept_character(')', "closing method")?;
388	                        self.accept_character('.', "closing method")?;
389	
390	                        Ok(new_descriptor_with_disambiguator(
391	                            name,
392	                            descriptor::Suffix::Method,
393	                            disambiguator,
394	                        ))
395	                    }
396	                    '/' => Ok(new_descriptor(name, descriptor::Suffix::Package)),
397	                    '.' => Ok(new_descriptor(name, descriptor::Suffix::Term)),
398	                    '#' => Ok(new_descriptor(name, descriptor::Suffix::Type)),
399	                    ':' => Ok(new_descriptor(name, descriptor::Suffix::Meta)),
400	                    '!' => Ok(new_descriptor(name, descriptor::Suffix::Macro)),
401	                    _ => Err(SymbolError::MissingDescriptor),
402	                }
403	            }
404	        }
405	    }
406	}
